import csv
import json
from collections import defaultdict

# ── Read data ──────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", "r", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append({
            "year": int(r["Year"]),
            "film": r["Film"],
            "composer": r["Composer"],
        })

# ── Parse composers ────────────────────────────────────────
# Multi-composer entries use ", " as separator
all_composers_flat = []
ceremony_composers = []  # list of lists
for r in rows:
    names = [n.strip() for n in r["composer"].split(", ")]
    ceremony_composers.append(names)
    all_composers_flat.extend(names)

unique_composers = sorted(set(all_composers_flat))
total_unique = len(unique_composers)

# ── Win counts per composer ────────────────────────────────
win_counts = defaultdict(int)
for names in ceremony_composers:
    for n in names:
        win_counts[n] += 1

sorted_composers = sorted(win_counts.items(), key=lambda x: (-x[1], x[0]))

# ── Repeat winner rate ─────────────────────────────────────
seen = set()
repeat_ceremonies = 0
for names in ceremony_composers:
    any_repeat = any(n in seen for n in names)
    if any_repeat:
        repeat_ceremonies += 1
    seen.update(names)

repeat_rate = round(repeat_ceremonies / len(rows) * 100, 1)

# ── Decade analysis ────────────────────────────────────────
decades = defaultdict(list)
for i, r in enumerate(rows):
    d = (r["year"] // 10) * 10
    decades[d].append(ceremony_composers[i])

decade_stats = {}
for d in sorted(decades.keys()):
    comps = set()
    for grp in decades[d]:
        comps.update(grp)
    decade_stats[d] = {
        "ceremonies": len(decades[d]),
        "unique_composers": len(comps),
    }

# Find decade with most unique winners
most_unique_decade = max(decade_stats.items(), key=lambda x: x[1]["unique_composers"])

# ── Repeat winners per decade ──────────────────────────────
decade_repeat = {}
for d in sorted(decades.keys()):
    seen_d = set()
    repeat_count = 0
    for grp in decades[d]:
        if any(n in seen_d for n in grp):
            repeat_count += 1
        seen_d.update(grp)
    decade_repeat[d] = repeat_count

# ── Era analysis ───────────────────────────────────────────
era_boundaries = {
    "Golden Age": (1934, 1959),
    "Silver Age": (1960, 1979),
    "Modern Era": (1980, 1999),
    "Contemporary Era": (2000, 2026),
}

era_data = {}
for era_name, (start, end) in era_boundaries.items():
    era_composers = []
    era_films = []
    for i, r in enumerate(rows):
        if start <= r["year"] <= end:
            era_composers.append(ceremony_composers[i])
            era_films.append(r["film"])
    flat = []
    for g in era_composers:
        flat.extend(g)
    wc = defaultdict(int)
    for n in flat:
        wc[n] += 1
    top = sorted(wc.items(), key=lambda x: -x[1])[:5]
    era_data[era_name] = {
        "ceremonies": len(era_films),
        "films": era_films,
        "unique_composers": len(set(flat)),
        "top_composers": top,
    }

# ── First-time winners per year ────────────────────────────
seen_global = set()
first_time_by_year = []
for i, r in enumerate(rows):
    new = [n for n in ceremony_composers[i] if n not in seen_global]
    first_time_by_year.append({"year": r["year"], "new": new, "count": len(new)})
    seen_global.update(ceremony_composers[i])

# ── Longest gaps between wins for repeat composers ─────────
composer_years = defaultdict(list)
for i, r in enumerate(rows):
    for n in ceremony_composers[i]:
        composer_years[n].append(r["year"])

gaps = []
for comp, years in composer_years.items():
    if len(years) >= 2:
        for j in range(1, len(years)):
            gaps.append({
                "composer": comp,
                "gap": years[j] - years[j-1],
                "from_year": years[j-1],
                "to_year": years[j],
            })
gaps.sort(key=lambda x: -x["gap"])

# ── Consecutive wins ───────────────────────────────────────
consecutive_streaks = []
for comp, years in composer_years.items():
    if len(years) >= 2:
        streak_start = years[0]
        streak_len = 1
        for j in range(1, len(years)):
            if years[j] == years[j-1] + 1:
                streak_len += 1
            else:
                if streak_len >= 2:
                    consecutive_streaks.append({
                        "composer": comp,
                        "length": streak_len,
                        "start": streak_start,
                        "end": years[j-1],
                    })
                streak_start = years[j]
                streak_len = 1
        if streak_len >= 2:
            consecutive_streaks.append({
                "composer": comp,
                "length": streak_len,
                "start": streak_start,
                "end": years[-1],
            })
consecutive_streaks.sort(key=lambda x: -x["length"])

# ── Notable names (first female winner from data) ──────────
# Hildur Guðnadóttir (2019) - first identifiably female name in dataset
# We identify this from the data itself

# ── Top composer film details ─────────────────────────────
top_composer_films = {}
for comp, _ in sorted_composers[:10]:
    films = []
    for i, r in enumerate(rows):
        if comp in ceremony_composers[i]:
            films.append({"year": r["year"], "film": r["film"]})
    top_composer_films[comp] = films

# ── Output JSON for JS embedding ───────────────────────────
output = {
    "total_ceremonies": len(rows),
    "total_unique_composers": total_unique,
    "max_wins": sorted_composers[0][1],
    "max_win_composers": [c for c, w in sorted_composers if w == sorted_composers[0][1]],
    "repeat_rate": repeat_rate,
    "repeat_ceremonies": repeat_ceremonies,
    "most_unique_decade": {
        "decade": f"{most_unique_decade[0]}s",
        "count": most_unique_decade[1]["unique_composers"],
    },
    "top_composers": [{"name": c, "wins": w} for c, w in sorted_composers if w >= 2],
    "top_composer_films": top_composer_films,
    "decade_stats": {f"{k}s": v for k, v in decade_stats.items()},
    "decade_repeat": {f"{k}s": v for k, v in decade_repeat.items()},
    "decade_unique": {f"{k}s": v["unique_composers"] for k, v in decade_stats.items()},
    "decade_ceremonies": {f"{k}s": v["ceremonies"] for k, v in decade_stats.items()},
    "era_data": {k: {
        "ceremonies": v["ceremonies"],
        "unique_composers": v["unique_composers"],
        "top_composers": [{"name": c, "wins": w} for c, w in v["top_composers"]],
    } for k, v in era_data.items()},
    "longest_gaps": gaps[:5],
    "consecutive_streaks": consecutive_streaks,
    "first_time_winners": [{"year": y["year"], "count": y["count"]} for y in first_time_by_year],
    "composer_years": {c: ys for c, ys in composer_years.items()},
}

print(json.dumps(output, indent=2, ensure_ascii=False))

